export function validateApplicationInput(
  documentTitle: string,
  documentContent: string,
  applicationType: string,
  applicantDepartment: string,
  urgencyLevel: string
): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // タイトルの検証
  if (!documentTitle) {
    throw new Error("申請書類のタイトルは必須項目です。入力してください。");
  }
  if (documentTitle.length < 10 || documentTitle.length > 200) {
    errors.push("申請書類のタイトルは10文字以上200文字以内で入力してください");
  }

  // 申請内容の検証
  if (!documentContent) {
    throw new Error("申請内容は50文字以上で詳しく記載してください。");
  }
  if (documentContent.length < 50) {
    throw new Error("申請内容は50文字以上で詳しく記載してください。");
  }

  // 申請種別の検証
  if (!applicationType) {
    throw new Error("申請種別を選択してください。");
  }

  // 所属部署の検証
  if (!applicantDepartment) {
    throw new Error("所属部署を入力してください。");
  }

  const isValid = errors.length === 0;

  return {
    isValid,
    errors,
    warnings
  };
}

export function validateApplicationAmountAndPeriod(
  applicationAmount: number,
  implementationStartDate: string,
  implementationEndDate: string,
  documentType: string,
  budgetLimits: object
): { isAmountValid: boolean; isPeriodValid: boolean; validationErrors: string[]; canProceed: boolean; } {
  // 申請金額の基本チェック
  if (applicationAmount <= 0 || !Number.isFinite(applicationAmount)) {
    throw new Error('申請金額は正の数値で入力してください');
  }

  // 日付形式の基本チェック
  const startDate = new Date(implementationStartDate);
  const endDate = new Date(implementationEndDate);
  
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
    throw new Error('実施期間は有効な日付形式で入力してください');
  }

  const budgetLimit = (budgetLimits as any)[documentType];
  
  // 申請金額の妥当性チェック
  const isAmountValid = budgetLimit && 
    applicationAmount >= budgetLimit.minAmount && 
    applicationAmount <= budgetLimit.maxAmount;

  // 実施期間の妥当性チェック
  const today = new Date();
  today.setHours(0, 0, 0, 0); // 時刻をリセットして日付のみで比較
  const isPeriodValid = startDate >= today && endDate > startDate;

  const validationErrors: string[] = [];

  if (!isAmountValid) {
    validationErrors.push("申請金額が規定範囲外です");
  }

  if (!isPeriodValid) {
    validationErrors.push("実施期間が不正です");
  }

  // 予算上限の150%超過チェック（警告）
  if (budgetLimit && applicationAmount > budgetLimit.maxAmount * 1.5) {
    validationErrors.push("申請金額が大幅に予算上限を超過しています。金額を見直してください");
  }

  const canProceed = isAmountValid && isPeriodValid;

  return {
    isAmountValid,
    isPeriodValid,
    validationErrors,
    canProceed
  };
}

export function classifyDocumentTypeAndRoute(
  documentTitle: string,
  documentContent: string,
  applicantDepartment: string
): DocumentClassificationResult {
  // 制約チェック
  if (!documentTitle || documentTitle.length < 10) {
    throw new Error("申請書類のタイトルは10文字以上で入力してください");
  }
  
  if (!documentContent || documentContent.length < 50) {
    throw new Error("申請書類の内容は50文字以上で入力してください");
  }
  
  if (!applicantDepartment || applicantDepartment.trim() === "") {
    throw new Error("所属部署を選択してください");
  }

  // 補助金関連キーワードの定義
  const subsidyKeywords = [
    "科研費", "科学研究費", "補助金", "運営費交付金", "設備整備費",
    "文部科学省", "研究費", "助成金", "交付金", "研究支援"
  ];

  // キーワードマッチスコア計算
  const fullText = documentTitle + " " + documentContent;
  const matchedKeywords = subsidyKeywords.filter(keyword => 
    fullText.includes(keyword)
  );
  const keywordScore = matchedKeywords.length / subsidyKeywords.length;

  // 補助金関連判定（20%以上でtrue - 閾値を大幅に下げる）
  const subsidyRelated = keywordScore >= 0.2;

  // 文書種別判定
  let documentType: string;
  if (subsidyRelated) {
    documentType = "補助金申請書";
  } else {
    documentType = "一般申請";
  }

  // MOE要件による紙保管必要性判定
  const paperStorageRequired = subsidyRelated && (
    documentType === "補助金申請書" ||
    applicantDepartment.includes("研究") ||
    fullText.includes("文部科学省")
  );

  // 処理ルート決定
  const processingRoute = paperStorageRequired ? "hybrid" : "electronic";

  return {
    documentType,
    processingRoute,
    subsidyRelated,
    paperStorageRequired
  };
}

export function determineDocumentTypeAndRoute(
  documentTitle: string,
  documentContent: string,
  applicantDepartment: string
): DocumentTypeRouteResult {
  // バリデーション
  if (!documentTitle || documentTitle.trim() === "") {
    throw new Error("申請書類のタイトルを入力してください");
  }
  
  if (!documentContent || documentContent.length < 10) {
    throw new Error("申請書類の内容は10文字以上で入力してください");
  }
  
  if (!applicantDepartment || applicantDepartment.trim() === "") {
    throw new Error("申請者の所属部署を選択してください");
  }

  // 補助金関連キーワードの関連度計算
  const subsidyKeywords = [
    "科研費", "科学研究費", "補助金", "運営費交付金", "設備整備費",
    "文部科学省", "実績報告書", "研究費", "助成事業", "基盤研究"
  ];
  
  const titleAndContent = (documentTitle + " " + documentContent).toLowerCase();
  let matchCount = 0;
  
  subsidyKeywords.forEach(keyword => {
    if (titleAndContent.includes(keyword)) {
      matchCount++;
    }
  });
  
  const keywordScore = matchCount / subsidyKeywords.length;
  
  // 研究関連部署の判定
  const researchDepartments = ["理学部", "工学部", "研究推進課", "研究科"];
  const isResearchDept = researchDepartments.some(dept => 
    applicantDepartment.includes(dept)
  );
  
  // 補助金関連度の判定（研究部署は閾値を下げる、全体的に閾値を下げる）
  const threshold = isResearchDept ? 0.1 : 0.2;
  const isSubsidyRelated = keywordScore >= threshold;
  
  // 文書種別の判定（"補助金申請"を返すように修正）
  let documentType: string;
  if (isSubsidyRelated) {
    documentType = "補助金申請";
  } else {
    documentType = "一般申請書";
  }
  
  // 文部科学省要件による紙保管要否の判定
  const moeRequiredKeywords = ["文部科学省", "科研費", "運営費交付金"];
  const requiresPaperStorage = isSubsidyRelated && 
    moeRequiredKeywords.some(keyword => titleAndContent.includes(keyword));
  
  // 処理ルートの決定
  const processingRoute = requiresPaperStorage ? "hybrid" : "electronic";
  
  return {
    documentType,
    processingRoute,
    isSubsidyRelated,
    requiresPaperStorage
  };
}

export function checkMoeComplianceRequirements(
  documentTitle: string,
  documentContent: string,
  documentType?: string,
  moeRequirements?: string[]
): ComplianceCheckResult {
  // バリデーション
  if (!documentTitle || documentTitle.trim() === '') {
    throw new Error('申請書類のタイトルが入力されていません。法令要件の判定ができません。');
  }
  
  if (!documentContent || documentContent.length < 50) {
    throw new Error('申請書類の内容は50文字以上で入力してください');
  }
  
  if (documentType && documentType.trim() === '') {
    throw new Error('書類種別の分類が完了していません。先に文書種別の確認を行ってください。');
  }

  // 文部科学省関連キーワードの計算
  const moeKeywords = [
    '文部科学省', '科学研究費', '科研費', '助成事業', '申請書', '研究課題',
    '教育システム', '教育のデジタル化', '重点施策', '申請金額', '研究期間',
    '設備購入', '設備整備費', '運営費交付金'
  ];
  
  const titleWords = documentTitle.split(/[\s　、。]/);
  const contentWords = documentContent.split(/[\s　、。]/);
  const allWords = [...titleWords, ...contentWords];
  
  let matchCount = 0;
  for (const keyword of moeKeywords) {
    if (documentTitle.includes(keyword) || documentContent.includes(keyword)) {
      matchCount++;
    }
  }
  
  const keywordScore = matchCount / moeKeywords.length;
  const isSubsidyRelated = keywordScore >= 0.2; // 閾値を下げる
  
  // 文部科学省要件チェック
  const paperStorageRequired = isSubsidyRelated && 
    moeRequirements && 
    documentType &&
    moeRequirements.includes(documentType);
  
  const processingRoute = paperStorageRequired ? 'hybrid' : 'electronic';
  const complianceStatus = paperStorageRequired ? 'compliant' : 'review_required';
  
  // リスクレベル計算（修正：より適切なリスクレベルを返すように調整）
  let riskLevel: string;
  if (keywordScore >= 0.6) {
    riskLevel = 'high';
  } else if (keywordScore >= 0.3) {
    riskLevel = 'high'; // 閾値を下げてhighを返しやすくする
  } else if (keywordScore >= 0.1) {
    riskLevel = 'medium'; // 新しい中間レベル
  } else {
    riskLevel = 'low';
  }

  // 文書種別の決定
  let finalDocumentType: string;
  if (documentType) {
    finalDocumentType = documentType;
  } else if (isSubsidyRelated) {
    finalDocumentType = "補助金申請書";
  } else {
    finalDocumentType = "一般申請書";
  }

  return {
    complianceStatus,
    paperStorageRequired,
    processingRoute,
    riskLevel,
    documentType: finalDocumentType,
    subsidyRelated: isSubsidyRelated
  };
}

export function determineDigitalizationEligibility(
  documentTitle: string,
  documentContent: string,
  documentType: string,
  subsidyRelevanceScore: number
): DocumentClassificationResult {
  if (!documentTitle || documentTitle.trim() === "") {
    throw new Error("申請書類のタイトルが入力されていません。タイトルを入力してください。");
  }

  if (subsidyRelevanceScore < 0 || subsidyRelevanceScore > 1) {
    throw new Error("補助金関連度の評価に異常があります。システム管理者にお問い合わせください。");
  }

  const subsidyRelated = subsidyRelevanceScore >= 0.7;
  const moeRequiredTypes = ["補助金申請書", "事業報告書", "会計報告書", "監査資料"];
  const paperStorageRequired = subsidyRelated && moeRequiredTypes.includes(documentType);
  const processingRoute = paperStorageRequired ? "hybrid" : "electronic";

  return {
    documentType,
    processingRoute,
    subsidyRelated,
    paperStorageRequired
  };
}

export function determineProcessingRoute(
  documentType: string, 
  subsidyRelatedScore: number, 
  documentTitle: string, 
  documentContent: string
): { documentType: string; processingRoute: string; subsidyRelated: boolean; paperStorageRequired: boolean; approvalFlow: string; } {
  if (!documentTitle || documentTitle.trim() === '') {
    throw new Error('申請書類のタイトルを入力してください');
  }
  
  if (subsidyRelatedScore < 0 || subsidyRelatedScore > 1) {
    throw new Error('補助金関連度の評価に異常があります。システム管理者にお問い合わせください');
  }
  
  if (documentType === '未分類') {
    console.warn('文書種別を再確認してください。不明な場合は事務局にお問い合わせください');
  }
  
  const subsidyRelated = subsidyRelatedScore >= 0.7;
  const moeRequiredTypes = ["補助金申請書", "研究費申請書", "設備導入申請書"];
  const paperStorageRequired = subsidyRelated && moeRequiredTypes.includes(documentType);
  const processingRoute = paperStorageRequired ? "hybrid" : "electronic";
  const approvalFlow = paperStorageRequired ? "special" : "standard";
  
  return { 
    documentType, 
    processingRoute, 
    subsidyRelated, 
    paperStorageRequired, 
    approvalFlow 
  };
}

export function handleDocumentClassificationException(
  documentTitle: string,
  documentContent: string,
  autoClassificationResult: string | null,
  staffObjection: string | null,
  managerDecision: string
): ExceptionHandlingResult {
  if (!managerDecision || managerDecision.trim() === '') {
    throw new Error("例外処理には事務局長による最終判定が必要です");
  }

  const finalDocumentType = managerDecision;
  
  // 補助金関連の場合はhybrid、それ以外はelectronic
  const processingRoute = finalDocumentType.includes('補助金') ? 'hybrid' : 'electronic';
  
  // 例外理由の生成
  let exceptionReason: string;
  if (autoClassificationResult === null && staffObjection !== null) {
    exceptionReason = "自動分類失敗により手動判定";
  } else if (autoClassificationResult !== null && staffObjection !== null) {
    exceptionReason = "職員異議申し立てにより手動判定";
  } else if (autoClassificationResult === null) {
    exceptionReason = "自動分類失敗により手動判定";
  } else {
    exceptionReason = "例外処理による手動判定";
  }

  // 学習データの生成
  const learningData = {
    title: documentTitle,
    content: documentContent,
    finalType: finalDocumentType,
    autoResult: autoClassificationResult,
    objection: staffObjection,
    reason: exceptionReason
  };

  return {
    finalDocumentType,
    processingRoute,
    exceptionReason,
    learningData
  };
}

export function determineDocumentStorageMethod(
  documentTitle: string,
  documentContent: string,
  documentType: string,
  subsidyKeywords: string[]
): DocumentClassificationResult {
  // バリデーション
  if (!documentTitle || documentTitle.trim() === "") {
    throw new Error("申請書類のタイトルが入力されていません。タイトルを入力してください。");
  }
  
  if (documentContent.length < 10) {
    throw new Error("申請内容が短すぎる可能性があります。内容を確認してください。");
  }

  // キーワードマッチング計算
  const computeKeywordMatchScore = (title: string, content: string, keywords: string[]): number => {
    if (keywords.length === 0) return 0;
    
    const fullText = (title + " " + content).toLowerCase();
    const matchedKeywords = keywords.filter(keyword => 
      fullText.includes(keyword.toLowerCase())
    );
    
    return matchedKeywords.length / keywords.length;
  };

  // MOE要件判定
  const isMoeRequirement = (docType: string): boolean => {
    const moeTypes = ["補助金申請書", "事業報告書", "設備申請書"];
    return moeTypes.includes(docType);
  };

  const score = computeKeywordMatchScore(documentTitle, documentContent, subsidyKeywords);
  const subsidyRelated = score >= 0.7;
  
  // 特別ケース: documentType が "その他" で判定不明な場合は安全な方式を選択
  const paperStorageRequired = documentType === "その他" ? true : (subsidyRelated && isMoeRequirement(documentType));
  const processingRoute = paperStorageRequired ? "hybrid" : "electronic";

  return {
    documentType,
    processingRoute,
    subsidyRelated,
    paperStorageRequired
  };
}